  const out: string[] = [];
  for (const part of parts) {
    if (part === "" || part === ".") {
      continue;
    }
    if (part === "..") {
      out.pop();
      continue;
    }
    out.push(part);
  }
  let id = out.join("/");
  if (id.endsWith(".md")) {
    id = id.slice(0, -3);
  }

  return id || null;
